+import { expect, test, vi } from "vitest";
+import { map } from "./map";
+import { pipe } from "./pipe";
+import { take } from "./take";
+
+const input = Object.freeze([1, 2, 3, 4]);
+const counts = [0, -1, -Infinity, NaN, 0.2, 1.9, 2.8, Infinity];
+
+test.each(counts)("normalizes count %s consistently", (count) => {
+  const normalized = count > 0 ? Math.floor(count) : 0;
+  const expected = input.slice(0, normalized);
+
+  expect(take(input, count)).toStrictEqual(expected);
+  expect(take(count)(input)).toStrictEqual(expected);
+  expect(pipe(input, take(count))).toStrictEqual(expected);
+});
+
+test("empty normalized counts do not invoke a lazy mapper", () => {
+  const mapper = vi.fn((value: number) => value * 2);
+
+  expect(pipe(input, map(mapper), take(0.2))).toStrictEqual([]);
+  expect(mapper).not.toHaveBeenCalled();
+});
+
+test.each([0.2, 1.9, 2.8])(
+  "positive fractional count %s limits lazy mapping to its floor",
+  (count) => {
+    const mapper = vi.fn((value: number) => value * 2);
+    const expected = input.slice(0, Math.floor(count)).map((value) => value * 2);
+
+    expect(pipe(input, map(mapper), take(count))).toStrictEqual(expected);
+    expect(mapper).toHaveBeenCalledTimes(Math.floor(count));
+  },
+);
+
+test("taking everything from readonly input returns a shallow copy without mutation", () => {
+  const result = take(input, Infinity);
+
+  expect(result).toStrictEqual(input);
+  expect(result).not.toBe(input);
+  expect(input).toStrictEqual([1, 2, 3, 4]);
+});
