+import { describe, expect, test } from 'vitest';
+import { object, string } from '../../schemas/index.ts';
+import type { Config } from '../../types/index.ts';
+import { ValiError } from '../../utils/index.ts';
+import { parser } from './parser.ts';
+import { parserAsync } from './parserAsync.ts';
+import { safeParser } from '../safeParser/safeParser.ts';
+import { safeParserAsync } from '../safeParser/safeParserAsync.ts';
+
+describe('parser config overrides', () => {
+  const schema = object({ a: string(), b: string() });
+  const captured: Config<never> = Object.freeze({
+    abortEarly: true,
+    message: 'captured',
+    lang: 'en',
+  });
+  const override: Config<never> = Object.freeze({
+    abortEarly: false,
+    message: 'per call',
+    lang: 'fr',
+  });
+  const input = { a: 1, b: 2 };
+
+  function getIssues(run: () => unknown): unknown[] {
+    try {
+      const result = run();
+      if (
+        typeof result === 'object' &&
+        result !== null &&
+        'issues' in result
+      ) {
+        return (result.issues as unknown[]) ?? [];
+      }
+      throw new Error('Expected a safe parser result');
+    } catch (error) {
+      if (error instanceof ValiError) {
+        return error.issues;
+      }
+      throw error;
+    }
+  }
+
+  test.each([
+    ['parser', parser],
+    ['safeParser', safeParser],
+  ] as const)('%s merges per-call config', (_name, createParser) => {
+    const func = createParser(schema, captured);
+
+    expect(getIssues(() => func(input))).toHaveLength(1);
+    expect(getIssues(() => func(input))[0]).toMatchObject({
+      message: 'captured',
+    });
+    expect(getIssues(() => func(input, override))).toHaveLength(2);
+    expect(
+      getIssues(() => func(input, override)).every(
+        (issue) => (issue as { message: string }).message === 'per call'
+      )
+    ).toBe(true);
+    expect(getIssues(() => func(input, { message: undefined }))).toHaveLength(
+      1
+    );
+    expect(getIssues(() => func(input, { message: undefined }))[0]).not.toMatchObject(
+      { message: 'captured' }
+    );
+    expect(getIssues(() => func(input, undefined))).toHaveLength(1);
+    expect(func.schema).toBe(schema);
+    expect(func.config).toBe(captured);
+    expect(override).toStrictEqual({
+      abortEarly: false,
+      message: 'per call',
+      lang: 'fr',
+    });
+  });
+
+  async function getAsyncIssues(run: () => unknown): Promise<unknown[]> {
+    try {
+      const result = await run();
+      if (
+        typeof result === 'object' &&
+        result !== null &&
+        'issues' in result
+      ) {
+        return (result.issues as unknown[]) ?? [];
+      }
+      throw new Error('Expected a safe parser result');
+    } catch (error) {
+      if (error instanceof ValiError) {
+        return error.issues;
+      }
+      throw error;
+    }
+  }
+
+  test.each([
+    ['parserAsync', parserAsync],
+    ['safeParserAsync', safeParserAsync],
+  ] as const)('%s merges per-call config', async (_name, createParser) => {
+    const func = createParser(schema, captured);
