+    expect(await getAsyncIssues(run)).toHaveLength(1);
+    expect(await getAsyncIssues(() => run(override))).toHaveLength(2);
+    expect(await getAsyncIssues(() => run({ message: undefined }))).toHaveLength(
+      1
+    );
+    expect(await getAsyncIssues(() => run(undefined))).toHaveLength(1);
+    expect(func.schema).toBe(schema);
+    expect(func.config).toBe(captured);
