import { describe, expect, test, vi } from "vitest";
import { map } from "./map";
import { pipe } from "./pipe";
import { take } from "./take";

const input = Object.freeze([1, 2, 3, 4]);

const cases = [
  [0, []],
  [-1, []],
  [-Infinity, []],
  [NaN, []],
  [0.2, []],
  [1.9, [1]],
  [2.8, [1, 2]],
  [Infinity, [1, 2, 3, 4]],
] as const;

describe("take count normalization", () => {
  test.each(cases)("normalizes %s", (count, expected) => {
    expect(take(input, count)).toStrictEqual(expected);
    expect(pipe(input, take(count))).toStrictEqual(expected);
  });

  test("normalizes counts before invoking a lazy upstream mapper", () => {
    for (const [count, expected] of cases) {
      const mapper = vi.fn((value: number) => value);

      expect(pipe(input, map(mapper), take(count))).toStrictEqual(expected);
      expect(mapper).toHaveBeenCalledTimes(expected.length);
    }
  });

  test("takes a shallow copy without mutating readonly input", () => {
    const result = take(input, Infinity);

    expect(result).toStrictEqual(input);
    expect(result).not.toBe(input);
    expect(input).toStrictEqual([1, 2, 3, 4]);
  });
});

